"""How Bun's first-party Rust is written: generated files, the largest files, and counts of the language features a port
to CeeSafe has to map (unsafe, FFI, macros, generics and traits, lifetimes, async, SIMD, inline asm, threads)."""
import collections, os, re, sys

ROOT = sys.argv[1]
SKIP = {".git", "node_modules", "target", "test", "tests"}
GEN = re.compile(r"@generated|DO NOT EDIT|auto-?generated|generated by", re.I)

PATTERNS = {
    "unsafe blocks/fns/impls": r"\bunsafe\s*(\{|fn\b|impl\b|extern\b)",
    "extern \"C\" items (FFI)": r"extern\s+\"C(-unwind)?\"",
    "#[no_mangle] / #[unsafe(no_mangle)] exports": r"no_mangle",
    "raw pointer types (*const/*mut)": r"\*(const|mut)\s",
    "macro_rules! definitions": r"\bmacro_rules!\s*\w+",
    "derive attributes": r"#\[derive\(",
    "proc-macro / attribute macros (#[xyz] non-std)": r"#\[(?!derive|cfg|allow|inline|test|doc|must_use|repr|warn|deny|no_mangle|unsafe|track_caller|cold|path|non_exhaustive|deprecated|rustfmt|expect|link|used|export_name|automatically_derived|global_allocator|macro_export|ignore|should_panic|target_feature|clippy)\w+",
    "trait definitions": r"^\s*(pub(\([^)]*\))?\s+)?(unsafe\s+)?trait\s+\w+",
    "impl ... for (trait impls)": r"^\s*(unsafe\s+)?impl\b[^{;]*\bfor\b",
    "dyn Trait uses": r"\bdyn\s+[A-Z]",
    "generic fns/types (<T ...>)": r"\b(fn|struct|enum|impl|trait)\s*\w*\s*<\s*('?[A-Za-z_]|const\s)",
    "explicit lifetimes ('a)": r"'[a-z_][a-z0-9_]*\b(?!')",
    "async fn / .await": r"\basync\s+(fn|move|\{)|\.await\b",
    "closures (|x| ...)": r"(?<![|&])\|[\w\s,:&*()<>]*\|\s*[{\w(]",
    "Box<dyn Fn / impl Fn": r"(dyn|impl)\s+Fn(Mut|Once)?\s*\(",
    "Rc/Arc": r"\b(Rc|Arc)\s*<",
    "RefCell/Cell": r"\b(RefCell|Cell)\s*<",
    "SIMD (std::arch / core::simd / portable_simd)": r"(std|core)::arch::|core::simd|std::simd|_mm\d*_|vld1q|uint8x16",
    "inline asm (asm!/global_asm!)": r"\b(asm|global_asm|naked_asm)!\s*\(",
    "threads/atomics (std::thread, Atomic*)": r"std::thread|\bAtomic(U|I|Bool|Ptr)\w*",
    "panics/unwrap/expect": r"\.(unwrap|expect)\(|\bpanic!\(",
    "Result ? operator": r"\)\?[;.)]",
    "match expressions": r"\bmatch\s+[^{]+\{",
    "const generics / const fn": r"\bconst\s+fn\b|<\s*const\s+\w+\s*:",
    "#[repr(C)] / #[repr(...)]": r"#\[repr\(",
    "transmute": r"\btransmute\b",
}
CRE = {k: re.compile(v, re.M) for k, v in PATTERNS.items()}

counts = collections.Counter()
by_area = collections.defaultdict(collections.Counter)
gen_lines, gen_files = 0, []
sizes = []
total = 0
for dirpath, dirnames, filenames in os.walk(os.path.join(ROOT, "src")):
    dirnames[:] = [d for d in dirnames if d not in SKIP]
    for fn in filenames:
        if not fn.endswith(".rs"):
            continue
        path = os.path.join(dirpath, fn)
        rel = os.path.relpath(path, ROOT)
        text = open(path, errors="replace").read()
        lines = sum(1 for l in text.splitlines() if l.strip() and not l.strip().startswith("//"))
        total += lines
        if GEN.search(text[:2000]) or "/generated" in rel or rel.endswith("_generated.rs"):
            gen_lines += lines
            gen_files.append((lines, rel))
            continue
        sizes.append((lines, rel))
        area = "/".join(rel.split("/")[:2])
        for k, rx in CRE.items():
            n = len(rx.findall(text))
            counts[k] += n
            by_area[area][k] += n

hand = total - gen_lines
print(f"Rust under src/: {total:,} lines; generated (by header or path): {gen_lines:,} in {len(gen_files)} files; "
      f"hand-written: {hand:,}")
print("\nlargest generated files:")
for n, rel in sorted(gen_files, reverse=True)[:10]:
    print(f"  {n:>8,}  {rel}")
print("\nlargest hand-written files:")
for n, rel in sorted(sizes, reverse=True)[:15]:
    print(f"  {n:>8,}  {rel}")
print("\nfeature counts in hand-written Rust (per 1,000 lines):")
for k in PATTERNS:
    print(f"  {k:52} {counts[k]:>9,}   {1000 * counts[k] / max(hand, 1):7.2f}")
FFI_KEY = "extern \"C\" items (FFI)"
print("\nunsafe and FFI by area (top 12 by unsafe):")
for area, c in sorted(by_area.items(), key=lambda x: -x[1]["unsafe blocks/fns/impls"])[:12]:
    print(f"  {area:32} unsafe {c['unsafe blocks/fns/impls']:>6,}  extern C {c[FFI_KEY]:>5,}  "
          f"raw ptr {c['raw pointer types (*const/*mut)']:>6,}  async {c['async fn / .await']:>4,}  "
          f"SIMD {c['SIMD (std::arch / core::simd / portable_simd)']:>4,}")
